#!/usr/bin/env bash
# Gegenprobe zu tests/smoke_lebendig.mjs.
# Jeder Fall baut EINEN Fehler in eine WEGWERF-KOPIE ein und besteht darauf, dass genau der
# zuständige Wächter rot wird. Der echte Baum wird nicht angefasst.
#   bash tests/gegenprobe_lebendig.sh
set -u
QUELLE="$(cd "$(dirname "$0")/.." && pwd)"
gefangen=0; durch=0
fall() { # name · erwartete rote Zeile · Sabotage-Befehl (läuft im Kopie-Ordner)
  local A; A="$(mktemp -d)"
  mkdir -p "$A/assets" "$A/docs/einladung/vendor"
  cp "$QUELLE/index.html" "$A/"; cp "$QUELLE/assets/schwarzes-loch.js" "$A/assets/"
  cp -r "$QUELLE/assets/video" "$A/assets/"; cp "$QUELLE/docs/einladung/index.html" "$A/docs/einladung/"
  cp -r "$QUELLE/docs/einladung/vendor/video" "$A/docs/einladung/vendor/"; cp -r "$QUELLE/docs/einladung/vendor/audio" "$A/docs/einladung/vendor/"
  cp "$QUELLE/docs/einladung/demo-zusammenarbeit.html" "$A/docs/einladung/"; mkdir -p "$A/docs/einladung/vendor/img"; cp "$QUELLE/docs/einladung/vendor/img/wie-zwei-sich-finden.webp" "$A/docs/einladung/vendor/img/"
  mkdir -p "$A/assets/discovery"; cp "$QUELLE/assets/milchstrasse-web.webp" "$QUELLE/assets/observatorium-galaxien-bg.jpg" "$A/assets/"; cp "$QUELLE/assets/discovery/galaxie-hintergrund.webp" "$A/assets/discovery/"; cp -r "$QUELLE/assets/galaxien" "$A/assets/"
  mkdir -p "$A/docs/discovery"; cp "$QUELLE/docs/discovery/index.html" "$A/docs/discovery/"; cp -r "$QUELLE/assets/discovery/licht" "$A/assets/discovery/"; cp "$QUELLE"/assets/discovery/*.webp "$A/assets/discovery/"
  ( cd "$A" && eval "$3" )
  local AUS; AUS="$(LEBENDIG_WURZEL="$A" node "$QUELLE/tests/smoke_lebendig.mjs" 2>&1)"
  if echo "$AUS" | grep -q "✗ .*$2"; then gefangen=$((gefangen+1)); echo "  gefangen: $1"
  else durch=$((durch+1)); echo "  DURCHGERUTSCHT: $1"; fi
  rm -rf "$A"
}
AUS="$(node "$QUELLE/tests/smoke_lebendig.mjs" 2>&1)" || { echo "ABBRUCH: Ausgangslage ist schon rot."; exit 2; }
echo "Ausgangslage grün."
fall "Kachel-Film fehlt"            "ms-3.mp4: Film liegt im Depot"        "rm assets/video/ms-3.mp4"
fall "Film lädt vorab"              "sonne.mp4: lädt nicht vorab"          "sed -i 's|preload=\"none\" aria-hidden=\"true\" data-src=\"assets/video/sonne.mp4\"|preload=\"auto\" aria-hidden=\"true\" data-src=\"assets/video/sonne.mp4\"|' index.html"
fall "Einladungs-Film fehlt"        "scene-5-tuer.mp4: Film liegt im Depot" "rm docs/einladung/vendor/video/scene-5-tuer.mp4"
fall "Truhen-Film fehlt"            "truhe-schluessel.mp4: Film liegt im Depot" "rm assets/video/truhe-schluessel.mp4"
fall "Tür-Fahrt fehlt"              "scene-5-schluessel-tuer.mp4: Film liegt im Depot" "rm docs/einladung/vendor/video/scene-5-schluessel-tuer.mp4"
fall "Schlüssel-Film fehlt"         "scene-5-schluessel.mp4: Film liegt im Depot" "rm docs/einladung/vendor/video/scene-5-schluessel.mp4"
fall "Musik fehlt"                  "Einladung: die Musik liegt im Depot" "rm docs/einladung/vendor/audio/ambient.mp3"
fall "Summton wieder da"            "Einladung: kein erzeugter Summton mehr" "sed -i 's|const AUDIO_LAUT = 0.55;|const AUDIO_LAUT = 0.55; const o1 = () => new AudioContext().createOscillator();|' docs/einladung/index.html"
fall "Tür-Film ohne Rückfall"       "ohne Tür-Film bleibt die Fahrt beim Scrollen" "sed -i \"s|filmModus = false; sec.classList.remove('film-modus');|sec.classList.remove('film-modus');|\" docs/einladung/index.html"
fall "Truhen-Film als harte Schleife" "der Truhen-Film blendet nach dem Ende zurück" "sed -i 's|<video class=\"vp-truhe-film\" muted playsinline|<video class=\"vp-truhe-film\" muted loop playsinline|' index.html"
fall "Skript nicht eingebunden"     "lädt assets/schwarzes-loch.js"        "sed -i 's|<script src=\"assets/schwarzes-loch.js\"></script>||' index.html"
fall "Rückfall-Film fehlt"          "der Rückfall-Film liegt im Depot"     "rm assets/video/schwarzes-loch.mp4"
fall "Knopf startet sichtbar"       "der Knopf startet versteckt"          "sed -i 's|id=\"bh-steuern\" hidden|id=\"bh-steuern\"|' index.html"
fall "Kachel schrumpft wieder"      "die offene Kachel nimmt zwei Spalten" "sed -i 's|aspect-ratio: auto; grid-column: span 2;|aspect-ratio: auto;|' index.html"
fall "Mindesthöhe entfernt"         "bleibt mindestens quadratisch"        "sed -i \"s|k.offsetWidth + 'px' : ''|''|\" index.html"
fall "Mini-Universen nicht gemalt"  "die Mini-Universen werden gemalt"     "sed -i 's|try { malMiniUniversum(el, lehre.shape, lehre.n); } catch (_e) {}||' index.html"
fall "Schleife läuft immer"         "die Schleife ruht"                    "sed -i 's|if (stage.offsetParent === null) {|if (false) {|' index.html"
fall "Hintergrund-Bild fehlt"       "gibt-es-nicht.webp.: liegt im Depot" "sed -i \"s|'assets/discovery/galaxie-hintergrund.webp',|'assets/discovery/gibt-es-nicht.webp',|\" index.html"
fall "Hintergrund wechselt nicht"   "gewechselt wird beim Öffnen"          "sed -i \"s#if (id === 'sonnen' || id === 'observatorium') wechsleGalaxieHintergrund(id);##\" index.html"
fall "Licht-Film fehlt"             "biolumineszenz: Licht-Film liegt im Depot" "rm assets/discovery/licht/biolumineszenz.mp4"
fall "Licht-Film lädt vorab"        "der Licht-Film lädt nicht vorab"      "sed -i \"s|film.preload = 'none'|film.preload = 'auto'|\" docs/discovery/index.html"
fall "Film ersetzt das Bild"        "liegt als Licht über dem Bild"        "sed -i 's|mix-blend-mode: screen; pointer-events: none;|pointer-events: none;|' docs/discovery/index.html"
fall "Screen nicht mehr Vollbild"   "füllen offen das ganze Fenster"       "sed -i 's|.observatorium-screen.active { position: fixed; inset: 0;|.observatorium-screen.active { inset: 0;|' index.html"
fall "Karte wieder offen"           "die sechs benannten Karten"           "sed -i 's|data-back-anchor=\"andock\" data-klapp|data-back-anchor=\"andock\"|' index.html"
fall "Kachel schließt nicht"        "die ganze Kachel schaltet"            "sed -i \"s|kachel.classList.toggle('is-open')|kachel.classList.add('is-open')|\" index.html"
fall "Galaxie dreht falsch herum"   "mit nachlaufenden Armen"              "sed -i 's|galaxy-spin 26s linear infinite reverse|galaxy-spin 26s linear infinite|' index.html"
fall "Apps wieder schmal"           "das Raster füllt die Kartenbreite"    "sed -i 's|class=\"card span-12\" data-back-anchor=\"endknoten\"|class=\"card span-5\" data-back-anchor=\"endknoten\"|' index.html"
fall "Einladungs-Film ersetzt Bild" "liegt als Licht über dem Standbild"  "sed -i 's|  mix-blend-mode: screen;\$||' docs/einladung/index.html"
fall "Klick-Hinweis wieder da"      "keine Klick-Hinweise"                 "sed -i 's|<div class=\"sun-caption\">|<div class=\"sun-caption\"><p class=\"sun-hint\">Klicke in die Sonne</p>|' index.html"
fall "Topologie ohne Einpassung"    "richtet sich nach der Fensterhöhe"    "sed -i \"s|svg.style.maxHeight = Math.max(300, freieHoehe()) + 'px';||\" index.html"
fall "Naht-Band fehlt"              "ein weiches Band über die Naht"       "sed -i 's|  bottom: -16vh; height: 58vh;|  height: 58vh;|' docs/einladung/index.html"
fall "Schlüssel-Kasten hart"        "läuft an den Rändern aus"             "sed -i 's|#scene-5 .key-host .key-image, #scene-5 .key-host .key-film, #scene-5 .key-host canvas {|#scene-5 .nichts {|' docs/einladung/index.html"
fall "Licht wieder grell"           "liegt gedämpft über dem Bild"         "sed -i 's|.licht-film.laeuft { opacity: 0.3; }|.licht-film.laeuft { opacity: 1; }|' docs/discovery/index.html"
fall "Finde-Film fehlt"             "Wie zwei sich finden: der Film liegt im Depot" "rm docs/einladung/vendor/video/wie-zwei-sich-finden.mp4"
fall "Finde-Film startet selbst"    "Wie zwei sich finden: der Film startet nur auf Tipp" "sed -i 's|<video controls playsinline preload=\"none\"|<video controls autoplay playsinline preload=\"none\"|' docs/einladung/demo-zusammenarbeit.html"
fall "Finde-Film ohne Standbild"    "Wie zwei sich finden: das Standbild liegt im Depot" "rm docs/einladung/vendor/img/wie-zwei-sich-finden.webp"
fall "Finde-Film ohne Untertitel"   "Wie zwei sich finden: der gesprochene Text liegt als Untertitel bei" "rm docs/einladung/vendor/video/wie-zwei-sich-finden.de.vtt"
fall "Schritte wieder unter dem Film" "Wie zwei sich finden: unter dem Film stehen keine Schritte" "sed -i 's|</figure>|</figure><div class=\\\"panel\\\">Schritt 1</div>|' docs/einladung/demo-zusammenarbeit.html"
fall "Endknoten-Karte wieder offen"  "Klappkarten: die sechs benannten Karten liegen unter einem Knopf" "sed -i 's|data-back-anchor=\\\"endknoten\\\" data-klapp|data-back-anchor=\\\"endknoten\\\"|' index.html"
fall "Schlüssel-Kasten ohne Breite"  "Einladung: der Schlüssel-Kasten hat am Handy eine Breite" "sed -i 's|#scene-5 .key-host { width: 100%; aspect-ratio: 5/4;|#scene-5 .key-host { aspect-ratio: 5/4;|' docs/einladung/index.html"
fall "Film bei ruhiger Darstellung weg" "Einladung: bei ruhiger Darstellung oder Datensparen startet ein Knopf die Filme" "sed -i 's|if (reducedMotion \|\| sparsam) filmKnopf(host, beobachten); else beobachten();|if (reducedMotion \|\| sparsam) film.remove(); else beobachten();|' docs/einladung/index.html"
fall "Erklärfilm fehlt"               "Tour: der Erklärfilm liegt im Depot" "rm assets/video/sage-in-einer-minute.mp4"
fall "Erklärfilm startet selbst"      "Tour: der Erklärfilm startet nur auf Tipp" "sed -i 's|<video controls playsinline preload=\\\"none\\\" poster=\\\"assets/video/sage-in-einer-minute.webp\\\"|<video controls autoplay playsinline preload=\\\"none\\\" poster=\\\"assets/video/sage-in-einer-minute.webp\\\"|' index.html"
fall "Tatsachen aus der Tour"         "Tour: die drei Tatsachen stehen weiter da" "sed -i 's|<strong>Geprüft wird bei dir.</strong>|<strong>Geprüft.</strong>|' index.html"
fall "Tatsachen-Film steht offen da"   "Tatsachen-Film: liegt zugeklappt hinter dem Pilz-Knopf" "sed -i 's|<figure class=\\\"warum-film\\\" id=\\\"tatsachen-film\\\" hidden>|<figure class=\\\"warum-film\\\" id=\\\"tatsachen-film\\\">|' index.html"
fall "Tatsachen-Film fehlt"            "Tatsachen-Film: Film und Standbild liegen im Depot" "rm assets/video/drei-tatsachen.mp4"
fall "Tatsachen-Film startet selbst"   "Tatsachen-Film: startet nur auf Tipp und lädt nicht vorab" "sed -i 's|<video controls playsinline preload=\\\"none\\\" poster=\\\"assets/video/drei-tatsachen.webp\\\"|<video controls autoplay playsinline preload=\\\"none\\\" poster=\\\"assets/video/drei-tatsachen.webp\\\"|' index.html"
fall "Tatsachen-Film ohne Untertitel"  "Tatsachen-Film: der gesprochene Text liegt als Untertitel bei" "rm assets/video/drei-tatsachen.de.vtt"
fall "Stempel-Clip wieder in der Tour" "Tour: der Stempel-Clip mit drei Stationen ist heraus" "sed -i 's|<ol class=\\\"tatsachen-text\\\">|<span data-video=\\\"assets/video/siegel.mp4\\\"></span><ol class=\\\"tatsachen-text\\\">|' index.html"
echo "═══ $gefangen gefangen · $durch durchgerutscht ═══"
[ "$durch" -eq 0 ]
